// parement dont toutes les pierres se moucheturent au même pas se lit en papier
// peint, quelle que soit la largeur de sa bande de teintes.
// Aucune n'est un bossage éclaté : « אֲבָנִים יְקָרֹת כְּמִדּוֹת גָּזִית מְגֹרָרוֹת בַּמְּגֵרָה מִבַּיִת
// וּמִחוּץ » (Melakhim I 7:9) — toutes ces faces sont SCIÉES, dedans et dehors. Ce qui
// change d'un bloc au suivant est le banc dont il sort et le lit sur lequel il est
// passé sous la scie, jamais l'outil.
struct Finition {
  float pas;      // pas de la moucheture large, en amot
  float lit;      // compression de ce pas sur la verticale : un bloc lité rend des bandes
  float force;    // amplitude de la moucheture, autour d'une moyenne qui ne bouge pas
  float couche;   // 1 si le bloc est passé COUCHÉ sous la scie : ses stries traversent
  float fin;      // pas de la moucheture fine, en amot
  float strie;    // ce que la scie laisse de lustre sur le champ
  float relief;   // ce que le bloc prend du relief de la nappe : sa porosité
  float lustre;   // écart de rugosité propre à la taille
};

Finition finition(float t){
  int k = int(t * 5.0);
  // Sciée debout : le parement que tout le blockout portait, et qui reste la référence
  // — les quatre autres se lisent CONTRE lui.
  if (k <= 0) return Finition(1.5, 1.0, 1.00, 0.0, 0.45, 0.090, 1.00,  0.00);
  // Sciée couchée : même outil, le bloc tourné sur son lit — les stries traversent.
  if (k == 1) return Finition(1.7, 1.0, 1.05, 1.0, 0.50, 0.075, 0.85, -0.03);
  // Piquée : le meleke vacuolaire, poreux jusqu'à la face, que la scie n'efface pas.
  if (k == 2) return Finition(0.9, 1.0, 1.55, 0.0, 0.22, 0.030, 1.60,  0.10);
  // Layée : reprise au ciseau en peigne serré, la seule dont la trace soit régulière.
  if (k == 3) return Finition(2.2, 1.0, 0.70, 1.0, 0.32, 0.130, 0.95,  0.02);
  // À banc : la pierre est LITÉE, et ses strates traversent la face en bandes.
  return Finition(2.6, 5.0, 1.45, 0.0, 0.60, 0.045, 1.10, -0.04);
}

// Distance au joint le plus proche, en amot, le long d'une coordonnée de monde.
// Le signe dit de quel côté du joint on est : la distance croît d'un côté, décroît de
// l'autre, et c'est ce signe-là qui donne les deux versants de la rainure.
float ecart(float coord, float taille, out float rang, out float sens){
  rang = coord / (taille * AMA);
  float f = fract(rang);
  sens = f < 0.5 ? 1.0 : -1.0;
  return min(f, 1.0 - f) * taille;
}

// Un joint plus fin que le pixel s'élargit jusqu'à lui en s'éclaircissant d'autant : un trait, pas un pointillé.
float horsJoint(float d, float largeur, float pixel){
  float l = max(largeur, pixel);
  return 1.0 - (1.0 - clamp(d / l, 0.0, 1.0)) * largeur / l;
}
float penteRampe(float d, vec2 rampe, float pixel){
  float l = max(rampe.y, pixel);
  return d >= rampe.x && d < rampe.x + l ? 1.0 / l : 0.0;
}

// Appareil de gazit. Le Tanakh mesure ces pierres : « אַבְנֵי עֶשֶׂר אַמּוֹת וְאַבְנֵי שְׁמֹנֶה
// אַמּוֹת » (Melakhim I 7:10) — deux longueurs, l'assise en tire une —, et les dit sciées
// lisses dedans et dehors, « מְגֹרָרוֹת בַּמְּגֵרָה מִבַּיִת וּמִחוּץ » (7:9). Tout le relief tient
// donc au joint creusé et au liseré ciselé qui le borde, jamais à un bossage éclaté.
// L'assise saillante et l'assise rentrante sont le אבן יוצא ואבן נכנס de Baba Batra 4a :
// c'est ce jeu-là, et non un placage, qui a fait renoncer Hérode à dorer le bâtiment.
// courte et longue : les deux longueurs de bloc, en amot, dont l'assise tire
// l'une. Un tambour de colonne est UNE pierre : il les prend énormes toutes les deux,
// ce qui supprime le joint vertical et ne laisse que le lit d'un tambour au suivant.
// Le dallage en rangées. usure ressort avec la teinte parce qu'elle se lit DEUX fois :
// la tache de vingt amot qui assombrit la dalle est le passage de la cour, et une dalle
// foulée est aussi plus lustrée. Le dessus d'un mur prend la première et pas la seconde
// — personne n'y marche.
// rovad : la largeur d'une rangée ; longueurs : les deux longueurs de dalle ; nuance : l'écart de valeur d'une dalle à l'autre.
struct Pavage { float rovad; vec2 longueurs; float nuance; };
const Pavage PAVAGE_DES_COURS = Pavage(ROVAD_DALLE, vec2(8.0, 10.0), 0.03);

void dalles(vec3 P, Pavage pavage, out vec3 teinte, out vec3 pente, out float rugo, out float usure,
            out vec4 photo){
  float g = grain(P * 7.0, empreinteMax() * 7.0);
  // Les rovadim se comptent en sortant du Heikhal, qui est à l'ouest : les rangées
  // s'empilent sur X et chacune court sur Z, d'un bout à l'autre de la cour.
  float ligne, sensX, sensZ;
  float dx = ecart(P.x, pavage.rovad, ligne, sensX);
  float num = floor(ligne);
  float tireRang = alea1(num * 1.7 + 3.1);
  float longueur = tireRang > 0.5 ? pavage.longueurs.y : pavage.longueurs.x;   // dans les cours : Melakhim I 7:10, comme les murs
  // Les joints en travers se décalent d'une rangée à la suivante : alignés, ils
  // feraient une grille, et la rangée cesserait de se lire comme une rangée.
  float v = P.z + (mod(num, 2.0) * 0.5 + tireRang * 0.37) * longueur * AMA;
  float colonne;
  float dz = ecart(v, longueur, colonne, sensZ);
  float d = min(dx, dz);
  float pixelX = empreinte(vec3(1.0, 0.0, 0.0)) / AMA, pixelZ = empreinte(vec3(0.0, 0.0, 1.0)) / AMA;
  float lit = min(horsJoint(dx, JOINT_DALLE, pixelX), horsJoint(dz, JOINT_DALLE, pixelZ));
  float tireDalle = alea3(vec3(floor(colonne), num, 0.0));
  usure = grain(P / (20.0 * AMA));
  teinte = vec3((1.0 + (g - 0.5) * 0.10) * (1.0 - pavage.nuance * 0.5 + tireDalle * pavage.nuance) * mix(0.70, 1.0, lit))
         * mix(vec3(1.0), OMBRE_JOINT, 0.45 * usure);
  vec3 dir = dx < dz ? vec3(sensX, 0.0, 0.0) : vec3(0.0, 0.0, sensZ);
  pente = penteRampe(d, vec2(0.0, JOINT_DALLE), dx < dz ? pixelX : pixelZ) * dir * (CREUX_DALLE / AMA);
  rugo = (g - 0.5) * 0.10;
  photo = vec4(vec3(tireDalle, tireRang, alea3(vec3(num, floor(colonne), 11.0))) * 13.0, 1.0);
}

// assise, longueurs courte et longue de bloc, débord, joint et liseré : tout en amot.
struct Appareil { float assise; float courte; float longue; float debord; float joint; float lisere; };
// Ce que tailler() lit en un point : les tirages du bloc, la pente de son joint et le masque du creux.
struct Bloc { float num; float parite; float tireAssise; float tireBloc; float tireFini;
              float u; vec3 axe; vec3 pente; float creux; };

Bloc tailler(vec3 P, vec3 N, Appareil a){
  Bloc b;
  float rang, sensZ, sensU;
  float dz = ecart(P.y, a.assise, rang, sensZ);
  b.num = floor(rang);
  b.parite = mod(b.num, 2.0);
  b.tireAssise = alea1(b.num * 1.7 + 3.1);
  float longueur = b.tireAssise > 0.5 ? a.longue : a.courte;
  b.axe = abs(N.x) > abs(N.z) ? vec3(0.0, 0.0, 1.0) : vec3(1.0, 0.0, 0.0);
  b.u = dot(P, b.axe);                            // la face décide de l'axe des joints
  // Les joints verticaux se décalent d'une assise à la suivante : alignés, ils font un
  // damier, que ne montre aucun appareil de pierre de taille.
  b.u += (b.parite * 0.5 + b.tireAssise * 0.37) * longueur * AMA;
  float colonne;
  float du = ecart(b.u, longueur, colonne, sensU);
  b.tireBloc = alea3(vec3(floor(colonne), b.num, 0.0));
  // La finition se tire À PART du banc. Sur le même tirage, la pierre la plus claire
  // serait toujours la plus piquée : les cinq finitions se liraient en cinq calcaires,
  // et le mur retomberait dans le nuancier qu'on cherche à quitter.
  b.tireFini = alea3(vec3(floor(colonne) + 19.0, b.num + 7.0, 3.0));
  float d = min(dz, du);
  // Le profil du bloc, en trois pentes : le joint, le liseré presque plat, le champ.
  // 0,62 de la course descend dans le joint, et il ne reste que 0,32 pour la marche du
  // bloc — une pierre sciée n'est proéminente que d'un cheveu. Plus haut, le relief
  // cernait chaque bloc d'un jonc clair et le mur rendait un carrelage.
  // Ce profil est linéaire par morceaux : sa dérivée s'écrit. C'est elle qui creuse le
  // joint pour la lumière, là où la teinte seule ne faisait qu'un trait peint.
  float pixelJoint = (dz < du ? empreinte(vec3(0.0, 1.0, 0.0)) : empreinte(b.axe)) / AMA;
  float dprofil = 0.62 * penteRampe(d, vec2(0.0, a.joint), pixelJoint)
                + 0.06 * penteRampe(d, vec2(a.joint, a.lisere), pixelJoint)
                + 0.32 * penteRampe(d, vec2(a.joint + a.lisere, 0.06), pixelJoint);
  // La marche d'assise n'agit que sur le LIT : un joint vertical sépare deux blocs du
  // même rang, qui affleurent. Les deux versants d'un même lit tombent dans des assises
  // de parité opposée, donc dans des marches opposées — c'est cette dissymétrie-là qui
  // se lit en débord, là où une rainure symétrique ne se lit qu'en trait.
  float marche = dz < du ? 1.0 + (b.parite * 2.0 - 1.0) * a.debord : 1.0;
  vec3 dir = dz < du ? vec3(0.0, sensZ, 0.0) : b.axe * sensU;
  b.pente = dprofil * marche * dir * (CREUX_M / AMA);
  // Le JOINT seul, sans le liseré : l'ombre s'arrête au fond de la rainure. Étalée sur
  // le liseré, elle cerne chaque bloc d'un cadre sombre que ne montre aucun mur ; le
  // liseré est de la pierre en plein soleil et ne doit rien perdre.
  b.creux = horsJoint(d, a.joint * 1.15 * marche, pixelJoint);
  return b;
}

void appareil(vec3 P, vec3 N, Appareil a, out vec3 teinte, out vec3 pente, out float rugo, out vec4 photo){
  if (abs(N.y) > 0.7) {                 // à plat : des dalles, une assise n'y a pas de sens
    float usure;
    dalles(P, PAVAGE_DES_COURS, teinte, pente, rugo, usure, photo);
    return;
  }
  Bloc b = tailler(P, N, a);
  Finition taille = finition(b.tireFini);
  pente = b.pente;
  // Une coulure, pas une tache : un bruit étiré à la verticale. Une tache sur un mur se
  // lit en défaut de matière ; une coulure se lit en pierre. Et une moucheture par-
  // dessus : le banc donne au bloc SA couleur, mais un bloc d'une seule couleur est un
  // échantillon de nuancier — le calcaire est nué à l'intérieur de chaque pierre.
  float coulure = COULURE_EXPOSEE * exposition() * smoothstep(0.52, 0.88, grain(vec3(P.x, P.y / 12.0, P.z) / (3.0 * AMA), empreinteMax() / (3.0 * AMA)));
  // La moucheture DÉVIE autour d'une moyenne fixe : d'un bloc au suivant c'est son
  // motif qui change, jamais sa valeur. La teinte est l'affaire du banc, et cinq
  // finitions qui s'éclairciraient l'une l'autre rendraient cinq calcaires.
  float mouchete = 0.14 + ((grain(P * vec3(1.0, taille.lit, 1.0) / (taille.pas * AMA), empreinteMax() * taille.lit / (taille.pas * AMA)) - 0.5) * 0.22
                         + (grain(P / (taille.fin * AMA), empreinteMax() / (taille.fin * AMA)) - 0.5) * 0.10) * taille.force;
  float f = b.parite * 0.10 + grain(P / (30.0 * AMA)) * 0.22 + b.tireBloc * 0.68;
  vec3 base = banc(f) * mix(vec3(1.0), OMBRE_JOINT, clamp(coulure + mouchete, 0.0, 1.0));
  teinte = mix(base * OMBRE_JOINT, base, b.creux);
  // La rugosité varie DANS le bloc, pas seulement d'un bloc à l'autre : sous un soleil
  // rasant c'est le lustre qui donne la surface, la teinte ne fait que la colorer.
  rugo = (b.tireBloc - 0.5) * 0.18 + (grain(P / (0.35 * AMA), empreinteMax() / (0.35 * AMA)) - 0.5) * 0.16 + taille.lustre;
#ifndef GRAIN_LEGER
  // « מְגֹרָרוֹת בַּמְּגֵרָה מִבַּיִת וּמִחוּץ » (Melakhim I 7:9) : ces blocs sont SCIÉS, et une
  // scie laisse sur le champ des stries parallèles de quelques centimètres de pas.
  // Elles ne sont que du lustre — aucune profondeur, donc aucune pente : c'est au
  // soleil rasant qu'un parement travaillé se sépare d'un aplat bruité, et la teinte
  // n'y peut rien. Étirées quarante fois le long de la face pour rester des stries.
  // Leur SENS est celui dans lequel la pierre est passée sous la scie : les unes
  // traversent la face, les autres la descendent. Deux voisins qui ne les portent pas
  // dans le même sens sont ce qui sépare un parement bâti d'une trame imprimée sur
  // tout le mur.
  vec2 scie = mix(vec2(0.7, 26.0), vec2(26.0, 0.7), taille.couche);
  rugo += (grain(vec3(b.u * scie.x, P.y * scie.y, 0.0), max(empreinte(b.axe) * scie.x, empreinte(vec3(0.0, 1.0, 0.0)) * scie.y)) - 0.5) * taille.strie;
#endif
  // Le carreau de la nappe se recale sur CHAQUE bloc. Photographié à plat et lu en
  // coordonnées de monde, le même éclat de calcaire revenait tous les 2,4 m sur toute
  // la façade : c'est cette récurrence-là, bien plus qu'une teinte, qui faisait lire
  // une image répétée. Le saut tombe dans le joint, où la dérivée d'écran explose sur
  // un pixel — c'est le fond de la rainure, et il est déjà à l'ombre.
  photo = vec4(vec3(b.tireBloc, b.tireAssise, b.tireFini) * 13.0, taille.relief);
}

void marbreHerode(vec3 P, vec3 N, out vec3 teinte, out vec3 pente, out float rugo, out vec4 photo){
  if (abs(N.y) > 0.7) {
    float usure;
    dalles(P, PAVAGE_DES_COURS, teinte, pente, rugo, usure, photo);
    return;
  }
  Bloc b = tailler(P, N, Appareil(ASSISE_HERODE, 8.0, 10.0, DEBORD, JOINT_MARBRE, LISERE_MARBRE));
  pente = b.pente;
  // « בְּאַבְנֵי כּוּחְלָא, שִׁישָׁא וּמַרְמְרָא » (Baba Batra 4a ; Soucca 51b), trois FROIDS selon Rashi,
  // tirés par assise entière : mêmes écarts au shesh que MARBRES_HERODE du blockout. C'est leur
  // écart qui fait la vague, « שהאבנים משונים במראיהן זו מזו » (Rashi sur Soucca 51b).
  vec3 marbre = b.tireAssise < 0.3333 ? vec3(1.00, 1.00, 1.00)
              : (b.tireAssise < 0.6667 ? vec3(0.83, 0.92, 1.02) : vec3(0.85, 0.97, 0.83));
  // L'assise porte la vague ; d'un bloc au suivant, à peine une nuance, sinon la façade tourne au patchwork.
  float f = b.parite * 0.10 + grain(P / (30.0 * AMA)) * 0.22 + b.tireBloc * 0.68;
  vec3 base = marbre * mix(vec3(0.97, 0.97, 0.98), vec3(1.03, 1.02, 1.00), clamp(f, 0.0, 1.0));
  teinte = mix(base * OMBRE_JOINT, base, b.creux);
  rugo = (b.tireBloc - 0.5) * 0.06;
  // Deux tirages du bloc sur chaque plan : celui de l'assise alignait la même veine sur tout le rang.
  photo = vec4(vec3(b.tireBloc, b.tireFini, b.tireBloc + b.tireFini) * 13.0, 1.0);
}

#ifdef PAROKHET
uniform sampler2D uParokhet;   // rgb hauteur du bombé, a masque de la figure
#endif
#ifdef GRAVURE
uniform sampler2D uGravure;    // rgb hauteur du modelé, a masque de la figure
varying vec2 vGravure;
#endif

#ifdef NAPPE
uniform sampler2D uNappeN;
uniform vec4 uCarreau;        // x carreaux/m, y couleur, z relief, w rugosité
uniform float uChroma;
#ifdef NAPPE_COULEUR
uniform sampler2D uNappeC;    // rgb albédo, a rugosité
uniform vec3 uMoyenne;
uniform float uRugoMoy;
#endif

// Trois prises pondérées par la normale de monde. La puissance 8 annule le mélange dès
// qu'on quitte l'arête d'un cube, et tout le blockout est en cubes : deux des trois
// prises n'y pèsent rien. Elles sont prises quand même — un branchement les rendrait
// plus chères que la texture qu'il évite, et la dérivée y deviendrait indéfinie.
vec3 poidsTri(vec3 N){
  vec3 w = pow(abs(N), vec3(8.0));
  return w / max(w.x + w.y + w.z, 1e-5);
}

vec4 nappe(sampler2D carte, vec3 p, vec3 w){
  return texture2D(carte, p.zy) * w.x + texture2D(carte, p.xz) * w.y
       + texture2D(carte, p.xy) * w.z;
}

// La nappe ressort en PENTE de monde et pas en normale : le joint écrit et le grain
// photographié sont alors deux gradients qui s'additionnent, au lieu de deux normales
// qui se disputent la dernière. Une normale tangente (x, y, z) vient d'une hauteur dont
// le gradient vaut -xy/z ; le plancher sur z borne ce que rend un texel presque couché.
vec3 penteNappe(vec3 p, vec3 w){
  vec3 x = texture2D(uNappeN, p.zy).xyz * 2.0 - 1.0;
  vec3 y = texture2D(uNappeN, p.xz).xyz * 2.0 - 1.0;
  vec3 z = texture2D(uNappeN, p.xy).xyz * 2.0 - 1.0;
  vec2 sx = -x.xy / max(x.z, 0.2), sy = -y.xy / max(y.z, 0.2), sz = -z.xy / max(z.z, 0.2);
  return vec3(0.0, sx.y, sx.x) * w.x + vec3(sy.x, 0.0, sy.y) * w.y
       + vec3(sz.x, sz.y, 0.0) * w.z;
}
#endif

// Ce que le temps fait à une paroi et qu'aucun blockout ne porte. La pluie de
// Jérusalem tombe l'hiver et descend : elle laisse des TRAÎNÉES, pas des taches, et
// c'est le seul vieillissement qui se lise en pierre plutôt qu'en défaut de matière.
// D'où un bruit étiré quatorze fois sur la hauteur, et un seuil haut — une paroi
// entièrement coulée serait sale, une paroi qui l'est par endroits est ancienne.
// force dit qui lave son parement : le Temple est en service et entretenu — le
// Mizbea'h est blanchi deux fois l'an (Middot 3:4) —, et une enceinte entièrement
// coulée s'y lit en ruine. La muraille des 500 amot et la ville la gardent entière.
// Mêmes valeurs que COULURE_ENTRETENUE / COULURE_EXPOSEE du blockout.
void patiner(vec3 P, vec3 N, float force, inout vec3 teinte, inout float rugo){
  float debout = 1.0 - abs(N.y);
  float trainee = smoothstep(0.54, 0.90, grain(P * vec3(2.6, 0.19, 2.6), empreinteMax() * 2.6)) * debout * force;
  teinte *= mix(vec3(1.0), OMBRE_JOINT, trainee * 0.22);
  rugo += trainee * 0.10;
}

// La Menora est מִקְשָׁה, et « מְשֻׁקָּדִים » : « שהן מכין בפטיש העשת עד שיהיה כולו שקדים שקדים » (Rambam
// sur Mena'hot 3:7). Chaque coup laisse une cupule en amande, deux fois plus longue que large
// sur la verticale ; sa pente est celle du carré de la distance à son centre, écrite et non
// dérivée à l'écran. Elle s'efface quand la cupule passe sous le pixel.
const float AMANDE = 0.006, CREUX_AMANDE = 0.0004;
void facettesAmande(vec3 P, vec3 N, inout vec3 pente, inout float rugo){
  float fin = 1.0 - smoothstep(0.25, 0.7, empreinteMax() / AMANDE);
  if (fin <= 0.0) return;
  vec3 taille = vec3(AMANDE, 2.0 * AMANDE, AMANDE);
  vec3 q = P / taille, i = floor(q), f = fract(q);
  float d = 9.0; vec3 r = vec3(0.0);
  for (int x = -1; x <= 1; x++)
  for (int y = -1; y <= 1; y++)
  for (int z = -1; z <= 1; z++) {
    vec3 c = vec3(float(x), float(y), float(z));
    vec3 v = c + vec3(alea3(i + c), alea3(i + c + 17.0), alea3(i + c + 41.0)) - f;
    float dv = dot(v, v);
    if (dv < d) { d = dv; r = v; }
  }
  vec3 g = -2.0 * CREUX_AMANDE * r / taille;
  pente += (g - N * dot(g, N)) * fin;
  rugo += (d - 0.35) * 0.04 * fin;
}

// Le dessus du Mizbea'h, en mètres de three (x, z) : 28 amot au carré, de x -52 à -24 et y -23 à 5 dans le blockout.
const vec4 SOMMET_MIZBEACH = vec4(-52.0 * AMA, -24.0 * AMA, -5.0 * AMA, 23.0 * AMA);
const float HAUT_MIZBEACH = 9.0 * AMA;

// Chaux sur pierres brutes (Middot 3:4) : la bosse d'une pierre, le grain du geste, et le pied sali par la cour.
void chaux(vec3 P, vec3 N, out vec3 teinte, out vec3 pente, out float rugo){
  float pixel = empreinteMax();
  vec3 t1 = normalize(abs(N.y) > 0.7 ? vec3(1.0, 0.0, 0.0) : cross(N, vec3(0.0, 1.0, 0.0)));
  vec3 t2 = cross(N, t1);
  vec3 q = P * 3.2, r = P * 13.0 + 7.3;
  float e = 0.12;
  float h = grainOblique(q, pixel * 3.2), g = grainOblique(r, pixel * 13.0);
  pente = ((grainOblique(q + t1 * e, pixel * 3.2) - h) * t1 + (grainOblique(q + t2 * e, pixel * 3.2) - h) * t2) * (0.16 / e)
        + ((grainOblique(r + t1 * e, pixel * 13.0) - g) * t1 + (grainOblique(r + t2 * e, pixel * 13.0) - g) * t2) * (0.05 / e);
  float couche = grainOblique(P * 0.7 + 3.1, pixel * 0.7);
  teinte = vec3(1.0 + (h - 0.5) * 0.05 + (couche - 0.5) * 0.07);
  float pied = (1.0 - smoothstep(0.0, 0.7 * AMA, P.y)) * (1.0 - abs(N.y));
  teinte *= mix(vec3(1.0), OMBRE_JOINT, pied * 0.30 * (0.6 + 0.8 * g));
  rugo = (g - 0.5) * 0.08;
}

// Le sang d'une semaine sur la chaux : « כָּל עֶרֶב שַׁבָּת מְלַבְּנִים אוֹתוֹ בְמַפָּה מִפְּנֵי הַדָּמִים » (Middot 3:4).
// Séché, il brunit ; mince, il ne laisse qu'un lavis rosé. Coins et cotes du blockout, en mètres de three (x, z).
const vec3 SANG = vec3(0.40, 0.09, 0.07), LAVIS_SANG = vec3(0.80, 0.58, 0.52);
const vec2 ZERIQA_NE = vec2(-23.0 * AMA, -6.0 * AMA), ZERIQA_SO = vec2(-53.0 * AMA, 24.0 * AMA);
const vec2 YESSOD_SO = vec2(-54.0 * AMA, 25.0 * AMA);

// Deux jets en diagonale, sous la ligne rouge, qui prennent le coin « כְּמִין גַּ״ם » (Rambam, Ma'asse HaKorbanot 5:6).
float zeriqa(vec3 P, vec2 coin, float pixel){
  float le_long = length(P.xz - coin) / AMA;
  float hauteur = P.y / AMA;
  float bord = (grainOblique(P * 2.2 + coin.xyx, pixel * 2.2) - 0.5) * 0.9;
  float jet = 1.0 - smoothstep(0.55, 1.0, length(vec2(le_long / 1.7, (hauteur - 3.4) / 1.1)) + bord);
  float gouttes = smoothstep(0.66, 0.74, grainOblique(P * 16.0 + 4.0, pixel * 16.0))
                * (1.0 - smoothstep(1.1, 1.8, length(vec2(le_long / 1.7, (hauteur - 3.4) / 1.3))));
  // Ce qui n'a pas pris coule jusqu'au yessod, en filets.
  float filet = smoothstep(0.62, 0.70, grainOblique(vec3(P.x * 7.0, P.y * 0.35, P.z * 7.0), pixel * 7.0))
              * (1.0 - smoothstep(1.0, 1.5, le_long)) * step(hauteur, 3.4) * smoothstep(0.9, 1.3, hauteur);
  return clamp(max(jet, max(gouttes, filet * 0.8)), 0.0, 1.0) * step(1.02, hauteur) * step(hauteur, 4.95);
}

// Le sang des 'hatatot, au doigt sur l'arête de chaque keren, « וְיוֹרֵד כְּנֶגֶד חֻדָּהּ שֶׁל קֶרֶן » (ibid. 5:7).
float arete(vec3 P, vec2 coin, float pixel){
  float loin = length(P.xz - coin) / AMA;
  float fin = 8.6 + 1.0 * grainOblique(vec3(coin * 3.0, 1.0), 0.0) + (grainOblique(P * 5.0, pixel * 5.0) - 0.5) * 0.6;
  return (1.0 - smoothstep(0.12, 0.40, loin + (grainOblique(P * 9.0, pixel * 9.0) - 0.5) * 0.25))
       * smoothstep(fin, fin + 0.4, P.y / AMA);
}

void sang(vec3 P, vec3 N, inout vec3 teinte, inout float rugo){
  float pixel = empreinteMax(), debout = 1.0 - abs(N.y);
  float tache = 0.0;
  if (FAMILLE == 18) {
    tache = max(zeriqa(P, ZERIQA_NE, pixel), zeriqa(P, ZERIQA_SO, pixel)) * debout;
    // Les shirayim, versés sur le yessod ouest et sud, gagnent les deux « חֳטָמִין » du coin sud-ouest (Middot 3:2).
    float versant = length(P.xz - YESSOD_SO) / AMA + (grainOblique(P * 1.6 + 9.0, pixel * 1.6) - 0.5) * 3.0;
    float flaque = (1.0 - smoothstep(2.0, 7.0, versant))
                 * smoothstep(0.7, 0.9, N.y) * (1.0 - smoothstep(1.05, 1.25, P.y / AMA)) * step(0.9, P.y / AMA);
    tache = max(tache, flaque * 0.9);
  } else {
    for (int k = 0; k < 4; k++) {
      vec2 coin = vec2(k < 2 ? -24.0 : -52.0, k % 2 == 0 ? -5.0 : 23.0) * AMA;
      tache = max(tache, arete(P, coin, pixel) * 0.85);
    }
  }
  if (tache <= 0.0) return;
  float epais = grainOblique(P * 3.0 + 1.7, pixel * 3.0);
  teinte *= mix(vec3(1.0), mix(LAVIS_SANG, SANG, smoothstep(0.3, 0.8, epais) * 0.8 + 0.2), tache);
  rugo -= tache * 0.12;
}

void matiere(vec3 P, vec3 N, out vec3 teinte, out vec3 pente, out float rugo, out vec3 feu){
  teinte = vec3(1.0); pente = vec3(0.0); rugo = 0.0; feu = vec3(1.0);
  // Où la nappe se prend pour ce point, et ce que ce point en garde de relief : un
  // appareil recale son carreau sur chaque bloc et lui donne sa porosité, le reste la
  // lit d'un seul tenant.
  vec4 photo = vec4(0.0, 0.0, 0.0, 1.0);
  // Le détail se fond sur la distance à l'oeil. La borne a suivi l'appareil : des blocs
  // de huit à dix amot tiennent à deux cents mètres, là où le module d'une ama
  // scintillait passé quarante et laissait la moitié des cadres en volumes gris.
  float loin = distance(P, cameraPosition);
  vec3 vue = (P - cameraPosition) / loin;
  // Plancher d'incidence : vu par la tranche, un plan étirerait le pixel à l'infini.
  regard = Regard(vue, max(abs(dot(N, vue)), 0.02), vPixel);
  float nettete = 1.0 - smoothstep(60.0, 200.0, loin);
  // Le relief se retire BIEN plus tôt que la couleur. Une teinte qui rétrécit sous le
  // pixel se moyenne toute seule ; une normale, non — elle bascule d'un pixel au
  // suivant et la façade se met à grésiller de blocs noirs et blancs.
  float finesse = 1.0 - smoothstep(16.0, 65.0, loin);
  if (FAMILLE == 1 || FAMILLE == 14) {   // le pourtour, et la muraille des 500 amot
    appareil(P, N, Appareil(ASSISE, 8.0, 10.0, DEBORD, JOINT, LISERE), teinte, pente, rugo, photo);
  }
  else if (FAMILLE == 13) {          // le dallage des cours : rangées, et lustre
    float usure;
    dalles(P, PAVAGE_DES_COURS, teinte, pente, rugo, usure, photo);
    // Une dalle passée est plus sombre ET plus lisse. C'est ce lustre, et non la
    // teinte, qui sépare une cour lavée d'une esplanade de grès ; même lecture qu'au
    // blockout, où l'usure descend la rugosité de 0,60 à 0,42.
    rugo -= usure * 0.18;
  }
  else if (FAMILLE == 22 || FAMILLE == 23) {   // la place du Kotel : pavé en rangs étroits, grandes dalles devant le mur
    float usure;
    Pavage pavage = Pavage(1.6, vec2(2.0, 3.2), 0.08);
    if (FAMILLE == 22) pavage = Pavage(0.9, vec2(1.3, 2.2), 0.14);
    dalles(P, pavage, teinte, pente, rugo, usure, photo);
    rugo -= usure * 0.18;
  }
  else if (FAMILLE == 19) {
    appareil(P - vec3(0.0, Z_PLACE_KOTEL * AMA, 0.0), N, Appareil(2.2917, 2.0, 6.0, DEBORD, 0.02, 0.3), teinte, pente, rugo, photo);
  }
  else if (FAMILLE == 20) {
    appareil(P - vec3(0.0, Z_KOTEL_OMEYYADE * AMA, 0.0), N, Appareil(1.6667, 1.5, 2.5, DEBORD, JOINT, 0.0), teinte, pente, rugo, photo);
  }
  else if (FAMILLE == 21) {
    appareil(P - vec3(0.0, Z_KOTEL_MAMELOUK * AMA, 0.0), N, Appareil(0.9926, 1.0, 1.6, DEBORD, JOINT, 0.0), teinte, pente, rugo, photo);
  }
  else if (FAMILLE == 11) {          // la ville : de la pierre de pays, pas du gazit
    appareil(P, N, Appareil(0.8, 1.5, 2.5, DEBORD, JOINT, LISERE), teinte, pente, rugo, photo);
  }
  else if (FAMILLE == 10) {          // tambour de colonne : pas de joint vertical
    // Sur un cylindre le joint vertical était pire qu'inutile : la face choisit son axe
    // sur la normale, qui bascule quatre fois autour du fût, et la trame sautait quatre
    // fois par colonne.
    appareil(P, N, Appareil(1.4, 1.0e4, 1.0e4, 0.0, JOINT, LISERE), teinte, pente, rugo, photo);
  }
  else if (FAMILLE == 9) {           // le bâtiment : trois marbres, polis et veinés
    marbreHerode(P, N, teinte, pente, rugo, photo);
  }
  else if (FAMILLE == 2) {                                   // marbre : veines lentes
    float v = grain(P * vec3(2.2, 5.0, 2.2) + grain(P * 1.1) * 2.0, empreinteMax() * 5.0);
    teinte = vec3(1.0 + (v - 0.5) * 0.13);
    rugo = (v - 0.5) * 0.06;
  }
  else if (FAMILLE == 3 || FAMILLE == 17) {                // métal battu au marteau
    // La nappe apporte le terni et les éraflures, pas les creux : une tôle laminée n'en
    // a pas. Or l'or du Heikhal est BATTU, et un creux de marteau ne se voit qu'au
    // reflet — c'est là, et jamais dans la teinte, que se joue le métal.
    // Le gradient se prend dans le plan de la face, pas sur les axes du monde : ces
    // feuilles couvrent des murs verticaux autant que des dessus de table.
    vec3 q = P * 6.0;
    vec3 t1 = normalize(abs(N.y) > 0.7 ? vec3(1.0, 0.0, 0.0) : cross(N, vec3(0.0, 1.0, 0.0)));
    vec3 t2 = cross(N, t1);
    float e = 0.10;
    float g = grain(q, empreinteMax() * 6.0);
    pente = ((grain(q + t1 * e, empreinteMax() * 6.0) - g) * t1 + (grain(q + t2 * e, empreinteMax() * 6.0) - g) * t2) * (0.055 / e);
    teinte = vec3(1.0 + (g - 0.5) * 0.05);
    rugo = (g - 0.5) * 0.10;
    if (FAMILLE == 17) facettesAmande(P, N, pente, rugo);
  }
  else if (FAMILLE == 4 || FAMILLE == 16) {                // bois : fil étiré
    // Le fil reste écrit — une planche de cèdre du Heikhal fait 20 amot de haut, et
    // aucune nappe d'un mètre ne porte une veine de cette longueur. Le lambris le garde
    // à moitié : c'est un bois choisi et poli.
    float fort = FAMILLE == 16 ? 0.5 : 1.0;
    float f = grain(P * vec3(9.0, 1.1, 9.0), empreinteMax() * 9.0);
    teinte = vec3(1.0 + ((f - 0.5) * 0.18 - fract(f * 7.0) * 0.06) * fort);
    rugo = (f - 0.5) * 0.10 * fort;
  }
  else if (FAMILLE == 5) {                                   // étoffe
    // La trame vient de la nappe : le sinus qui la portait valait 38 périodes au mètre
    // et grésillait dès deux pas de recul, ce qu'aucun mipmap ne pouvait rattraper.
    teinte = vec3(1.0 + (grain(P * 45.0, empreinteMax() * 45.0) - 0.5) * 0.10);
    rugo = -0.03;
#ifdef PAROKHET
    // Le motif tissé, lu par (y, z) de monde sur les 20 × 40 amot du rideau : la
    // hauteur (r) se dérive en pente, comme le joint d'un bloc, et (g, b) choisit la
    // face qui affleure. u court vers -z (le nord de Blender est le -z de three), v
    // monte avec y.
    vec2 uv = vec2(0.5 - P.z / (20.0 * AMA), (P.y - SOL_BAYIT) / (40.0 * AMA));
    vec2 pas = TEXEL_PAROKHET * 2.0;
    float dU = texture2D(uParokhet, uv + vec2(pas.x, 0.0)).r - texture2D(uParokhet, uv - vec2(pas.x, 0.0)).r;
    float dV = texture2D(uParokhet, uv + vec2(0.0, pas.y)).r - texture2D(uParokhet, uv - vec2(0.0, pas.y)).r;
    pente = BOMBE_PAROKHET * vec3(0.0, dV / (2.0 * pas.y * 40.0 * AMA), -dU / (2.0 * pas.x * 20.0 * AMA));
    vec4 tisse = texture2D(uParokhet, uv);
    vec3 face = mix(mix(FOND_PAROKHET, CHAUD_PAROKHET, tisse.b),
                    mix(CLAIR_PAROKHET, CLAIR_CHAUD_PAROKHET, tisse.b), tisse.g);
    teinte *= face / FOND_PAROKHET;
#endif
  }
  else if (FAMILLE == 6) {                                   // eau : ride lente
    // La ride se voit au reflet, pas à la teinte : c'est la seule famille hors pierre
    // dont la hauteur vaille une pente, et son bruit se dérive au pas fini, en monde.
    vec3 q = P * 5.5 + vec3(0.0, uTemps * 0.12, 0.0);
    float r = grain(q);
    float e = 0.03;
    pente = vec3(grain(q + vec3(e, 0.0, 0.0)) - grain(q - vec3(e, 0.0, 0.0)), 0.0,
                 grain(q + vec3(0.0, 0.0, e)) - grain(q - vec3(0.0, 0.0, e))) * (0.35 / e);
    teinte = vec3(1.0 + (r - 0.5) * 0.08);
    rugo = -0.02;
  }
  else if (FAMILLE == 7) {                                   // enduit à la chaux
    float g = grain(P * 11.0, empreinteMax() * 11.0), fin = grain(P * 47.0, empreinteMax() * 47.0);
    teinte = vec3(1.0 + (g - 0.5) * 0.20 + (fin - 0.5) * 0.09);
    rugo = (g - 0.5) * 0.12;
  }
  else if (FAMILLE == 15) {                                  // rocher nu : ni joint ni lit
    // Relief dérivé dans le plan de la face, comme le métal.
    vec3 t1 = normalize(abs(N.y) > 0.7 ? vec3(1.0, 0.0, 0.0) : cross(N, vec3(0.0, 1.0, 0.0)));
    vec3 t2 = cross(N, t1);
    vec3 q = P * 7.0;
    float e = 0.08;
    float g = grainNorme(q);
    pente = ((grainNorme(q + t1 * e) - g) * t1 + (grainNorme(q + t2 * e) - g) * t2) * (0.30 / e);
    teinte = vec3(0.80 + grainNorme(P * 2.2 + 17.0) * 0.40 + (grainNorme(P * 40.0) - 0.5) * 0.12);
    rugo = 0.10;
  }
  else if (FAMILLE == 12) {                                  // gehalim : les braises
    // Le charbon se lit à deux échelles : des morceaux qui se cassent, et le réseau de
    // fentes où le rouge affleure entre eux. Le maillage ne porte que le tas.
    // Un charbon fait la taille d'un poing, une fente celle d'un doigt : au mètre, le
    // réseau se lisait en coulée de lave.
    vec3 q = P * 15.0;
    float e = 0.014;
    pente = vec3(grain(q + vec3(e, 0.0, 0.0)) - grain(q - vec3(e, 0.0, 0.0)), 0.0,
                 grain(q + vec3(0.0, 0.0, e)) - grain(q - vec3(0.0, 0.0, e))) * (0.13 / e);
    // Le creux entre deux charbons, et la fente qui court sur l'un d'eux. La fente est
    // une CRÊTE de bruit, pas un seuil : un seuil donne des plaques, une crête un trait.
    float creux = 1.0 - smoothstep(0.34, 0.62, grainNorme(P * 8.0));
    float fente = 1.0 - smoothstep(0.0, 0.06, abs(grainNorme(P * 21.0) - 0.5));
    // En plein jour un bûcher est GRIS : la cendre en couvre la moitié, et le rouge ne
    // sort qu'où une fente tombe dans un creux. Un charbon qui rougeoie sur toute sa
    // surface est de la lave.
    float cendre = smoothstep(0.40, 0.74, grainNorme(P * 2.4 + 31.0)) * smoothstep(0.0, 0.6, N.y);
    teinte = mix(vec3(0.07 + 0.16 * grainNorme(q) + 0.06 * grainNorme(P * 44.0)),
                 vec3(1.75, 1.66, 1.52), cendre);
    rugo = 0.32 - fente * 0.20;
    // Le tirage passe par le rewa'h entre les gzirin : la braise RESPIRE, lentement.
    // Un clignotement rapide se lit en néon, pas en feu.
    float souffle = 0.5 + 0.5 * bruit(P * 0.9 + vec3(0.0, uTemps * 0.5, 0.0));
    float coeur = fente * creux * souffle * (1.0 - cendre);
    feu = vec3(0.85 * coeur) * (vec3(1.0) + vec3(0.0, 0.5, 1.1) * coeur * coeur);
  }
  else if (FAMILLE == 18) {
    chaux(P, N, teinte, pente, rugo);
    sang(P, N, teinte, rugo);
  }
  else if (FAMILLE == 8) {                                   // chaux noircie par le feu
    chaux(P, N, teinte, pente, rugo);
    float pixel = empreinteMax();
    // La bande du blockout (enduit_noirci, 7,5 à 10,5 amot) : blanchi deux fois l'an (Middot 3:4), il n'est noir qu'en haut.
    float montee = smoothstep(7.5 * AMA, 10.5 * AMA, P.y);
    // La fumée passe la lèvre et redescend en coulées inégales : un seuil qui suit un bruit étiré en hauteur et
    // lui-même déformé — sans la déformation, les coulées tombaient au même pas, en dents de scie.
    vec3 fil = P * vec3(1.1, 0.22, 1.1) + (grainOblique(P * 0.7 + 23.0, pixel * 0.7) - 0.5) * 2.5;
    float coulee = grainOblique(fil, pixel * 1.1) * (0.7 + 0.3 * grainOblique(P * vec3(4.0, 0.8, 4.0), pixel * 4.0));
    float seuil = 0.32 - 0.30 * coulee;
    float paroi = smoothstep(seuil, seuil + 0.16, montee) * (0.60 + 0.40 * grainOblique(P * 0.9, pixel * 0.9));
    float dessus = smoothstep(0.5, 0.9, N.y) * step(HAUT_MIZBEACH - 0.1, P.y);
    // « אַמָּה… מְקוֹם הַקְּרָנוֹת, אַמָּה… מְקוֹם הִלּוּךְ רַגְלֵי הַכֹּהֲנִים » (Middot 3:1) : deux amot de bord, et le feu au-delà.
    vec4 s = SOMMET_MIZBEACH;
    float bord = min(min(P.x - s.x, s.y - P.x), min(P.z - s.z, s.w - P.z)) / AMA;
    float foule = smoothstep(0.8, 1.2, bord) * (1.0 - smoothstep(1.8, 2.3, bord));
    float feuLit = smoothstep(1.8, 2.6, bord);
    // Le feu cuit la chaux par plaques, et le passage des cohanim la garde plus claire.
    float brulure = mix(0.55, 1.0, grainOblique(P * 0.45 + 11.0, pixel * 0.45)) * mix(0.75, 1.0, feuLit) * (1.0 - 0.35 * foule);
    float suie = max(paroi, dessus * brulure);
    // La cendre se couche en congères d'une ama que le vent tourne : un champ lent, déformé par un plus lent encore.
    // Le passage est balayé ; la cendre ne s'y garde qu'en poussière.
    vec3 derive = vec3(grainOblique(P * 0.25, pixel * 0.25), 0.0, grainOblique(P * 0.25 + 5.0, pixel * 0.25)) - 0.5;
    vec3 c = P * 0.9 + derive * 2.2;
    float epaisseur = grainOblique(c, pixel * 0.9);
    // Le bord d'une congère est poudreux : le seuil tremble d'une octave fine, sans descendre jusqu'au grain.
    float bordCendre = epaisseur + (grainOblique(P * 4.5 + 2.0, pixel * 4.5) - 0.5) * 0.14;
    float cendre = smoothstep(0.45, 0.62, bordCendre) * dessus * mix(0.25, 1.0, max(feuLit, 1.0 - foule));
    float ec = 0.10;
    pente += vec3(grainOblique(c + vec3(ec, 0.0, 0.0), pixel * 0.9) - epaisseur, 0.0,
                  grainOblique(c + vec3(0.0, 0.0, ec), pixel * 0.9) - epaisseur) * (0.10 / ec) * cendre;
    // De près, la chaux brûlée et la cendre ont un grain ; il s'efface avec le pixel au lieu de moucheter.
    float poudre = grainOblique(P * 7.0, pixel * 7.0) - 0.5, fin = grainOblique(P * 29.0, pixel * 29.0) - 0.5;
    vec3 brule = mix(vec3(1.0), NOIR_SUIE * (1.0 + poudre * 0.35 + fin * 0.25), suie);
    teinte *= mix(brule, GRIS_CENDRE * (1.0 + poudre * 0.18 + fin * 0.14), cendre * 0.85);
    rugo += suie * 0.16 + cendre * 0.10;
    sang(P, N, teinte, rugo);
  }
  // Le dehors seulement : le Heikhal n'a pas vu la pluie, et l'enduit se refait.
  if (FAMILLE == 1 || FAMILLE == 10 || FAMILLE == 11 || FAMILLE == 14 || FAMILLE >= 19) patiner(P, N, exposition(), teinte, rugo);
#ifdef GRAVURE
  // Le modelé d'une plaque gravée, dérivé de la carte au pas du texel. u de la tuile
  // court le long de la paroi — l'axe x de Blender sur un mur nord ou sud, l'axe y
  // (le -z de three) sur un mur ouest — et v monte. Les flancs de la taille ne portent
  // pas de modelé.
  {
    vec3 tu = abs(N.z) > abs(N.x) ? vec3(1.0, 0.0, 0.0) : vec3(0.0, 0.0, -1.0);
    vec2 pas = vec2(TEXEL_GRAVURE, 0.0);
    float dU = texture2D(uGravure, vGravure + pas.xy).r - texture2D(uGravure, vGravure - pas.xy).r;
    float dV = texture2D(uGravure, vGravure + pas.yx).r - texture2D(uGravure, vGravure - pas.yx).r;
    pente += (RELIEF_GRAVURE * TAILLE_TUILE / CADRE_GRAVURE / (2.0 * TEXEL_GRAVURE))
           * (dU * tu + dV * vec3(0.0, 1.0, 0.0)) * (1.0 - step(0.5, abs(N.y)));
  }
#endif
